{
  "pains": [
    {
      "id": "pain:support-never-calls-back",
      "statement": "When the POS breaks I can't get anyone at support who can fix it, and the callback they promise never comes.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "A card reader, handheld or online ordering fault that Tier 1 support cannot diagnose, with long holds and callbacks that never arrive.",
        "operational": "The owner calls again, starts the case over with a new rep who gives a different answer, and keeps running service around the broken device.",
        "personal": "The owner loses whole days to the phone: one reviewer spent over twelve hours on Toast support in a single day, another says support failures cost two restaurants thousands of dollars.",
        "personal_note": "Read from the chris and Jason Wright reviews on Trustpilot; no source describes the effect on the owner's family or health."
      },
      "workflow": "During service, when a Toast card reader or handheld fails or the online ordering menu misbehaves, the owner phones Toast support, gets escalated to a case number, and waits for a callback while the floor keeps running.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "switching",
        "what": "A two-restaurant owner says Toast support glitches cost thousands of dollars and that they moved to SpotOn.",
        "cites": ["src:5"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "The first weeks after go-live, when the system is new and the owner still depends on support to make it work.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "If I ever get through to support, they typically have to call me back with a solution...which never happens.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I have been on toast customer service for over 12 hours today.",
              "cites": ["src:5"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "6 weeks in they couldn't figure out what was wrong with my system",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "Tier 1 support know next to nothing.",
              "cites": ["src:2"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "Due to some glitches, their support has cost my 2 restaurants literally thousands of dollars.",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "customer support is terrible!!!!!",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Hours on hold in the middle of the day and, for a two-restaurant owner, thousands of dollars in sales lost to glitches nobody fixed.",
          "fears": "That the system stays broken for weeks because nobody at the vendor can figure out what is wrong.",
          "dream_outcome": "One call, a rep who knows the system, and the problem fixed the same day."
        }
      },
      "relief": {
        "line": "Fast fix. One call to a rep who knows the system and service carries on.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "Fast customer service, great POS solution and inventory management",
            "cites": ["src:5"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Not found. No buyer describes what changes in their standing a year after support stopped being a problem.",
        "says": [],
        "gap": "Read the 4 and 5 star reviews on Trustpilot page 3; they praise fast reps and ease of use, none describes a lasting change past relief."
      },
      "segments": ["seg:independent", "seg:multi"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company addresses support; the reviews are about Toast's own support. Support staffing and first-call resolution would, not a product feature.",
      "cites": ["src:3", "src:5", "src:2", "src:4"]
    },
    {
      "id": "pain:card-sales-stop-when-system-down",
      "statement": "When the POS goes down mid-service we can't take cards, offline transactions go missing, and I lose the day's sales.",
      "element": "b2b:ease_of_doing_business:stability",
      "shape": {
        "surface": "The terminal, dashboard and team app stop working, cards decline or queue offline, and some queued offline transactions never push through.",
        "operational": "Staff write card numbers on paper and key them in later, ask for cash only, or the owner buys a second processor as a backup.",
        "personal": "An outage on payroll day leaves the owner unable to pay staff on time: one owner said it left all of their employees in the lurch.",
        "personal_note": "From the anchohoney post in the Square community thread."
      },
      "workflow": "At the counter during a shift, when the POS vendor's cloud goes down: the card terminal stops taking payments, offline-mode transactions queue on the tablet, and next morning the owner checks which queued charges went through.",
      "type": "felt",
      "confidence": "medium",
      "priority": 2,
      "felt_evidence": {
        "kind": "paying",
        "what": "A Square merchant buys a PayPal POS terminal as a backup after outages, saying it would pay for itself.",
        "cites": ["src:7"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "A vendor-wide outage like Square's of 7 September 2023, after which merchants posted losses and started looking at other systems.",
          "cites": ["src:7"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I'm getting sick of Square's system outages affecting our sales.",
              "cites": ["src:6"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "We were down $456 Thursday, but over by $88 Friday and $185 Saturday.",
              "cites": ["src:7"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I left a tablet open with over $300 of offline transactions when I left for the evening.",
              "cites": ["src:7"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "caused thousands of dollars in lost sales, as well as completely disrupted our payroll run, leaving all of our employees in the lurch.",
              "cites": ["src:7"]
            },
            {
              "situation": "when_looking",
              "verbatim": "this has motivated me to look at the marketplace and see if there is a better fit.",
              "cites": ["src:7"]
            },
            {
              "situation": "venting",
              "verbatim": "The toast server freezes up daily.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Hundreds to thousands of dollars in sales per outage, plus offline charges that never settle.",
          "fears": "That the next outage lands on a busy day or a payroll run and staff go unpaid.",
          "dream_outcome": "Cards keep working through any outage and every offline charge settles once the system is back."
        }
      },
      "relief": {
        "line": "Covered. The backup caught the sale the main system lost.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "Thankfully, my backup card processor (Stripe) had a log of it.",
            "cites": ["src:7"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Not found. No buyer describes a year without outage worry.",
        "says": [],
        "gap": "Read both Square community outage threads and Trustpilot page 3; merchants describe backups, none describes a lasting change in how they run the business."
      },
      "segments": ["seg:quick", "seg:independent"],
      "feature_ref": "feat:offline",
      "feature_note": "Offline mode is the claimed answer, but Square merchants report queued offline transactions that vanished, so the pain is offline mode that cannot be trusted. Evidence is from Square's community; the one Toast-specific source is a daily freeze complaint.",
      "cites": ["src:6", "src:7", "src:5"]
    },
    {
      "id": "pain:locked-in-surprise-fees",
      "statement": "Toast locked me into a contract and their processor, then hit me with fees the rep never mentioned and made it hard to leave.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Unannounced deposits, software fees that rise, charges after cancellation, and a remaining-contract bill when the owner tries to leave.",
        "operational": "The owner disputes charges, chases cancellations for months, and pays out the contract or switches vendors.",
        "personal": "An owner closed during COVID was asked to pay about $8,000 to cancel.",
        "personal_note": "From the sancar dumlupinar review on CardFellow."
      },
      "workflow": "At signing with the Toast sales rep and again when the owner checks the business bank account and sees an ACH debit or fee they were not told about, or calls to cancel and is held to the two-year term.",
      "type": "felt",
      "confidence": "high",
      "priority": 3,
      "felt_evidence": {
        "kind": "switching",
        "what": "An owner of two restaurants left Toast for SpotOn, saying it works for half the price.",
        "cites": ["src:5"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "A closure or slowdown that makes the owner try to cancel mid-contract, as during COVID closures.",
          "cites": ["src:2"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Toast is asking me to pay $8k for canceling my membership.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "You're locked in to a single credit card processor.",
              "cites": ["src:2"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I noticed a $500.00 deposit fee that my representative for toast said nothing about.",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Toast still expected us to pay the remaining contractual amount.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "They nickel and dime you to death.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Went with SpotOn and seems to wok well for 1/2 the price also.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Unplanned debits from the business account and thousands to exit a contract.",
          "fears": "That the fees keep climbing and there is no way out without paying the rest of the term.",
          "dream_outcome": "A price they knew at signing and the freedom to leave without a penalty."
        }
      },
      "relief": {
        "line": "Half the bill. Same job done for half the price after switching.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "Went with SpotOn and seems to wok well for 1/2 the price also.",
            "cites": ["src:5"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Not found. No buyer describes life a year after leaving a locked-in contract.",
        "says": [],
        "gap": "Read Trustpilot 1-star and page 3 and both CardFellow pages; switchers mention price, none describes a lasting change."
      },
      "segments": ["seg:independent"],
      "feature_ref": null,
      "feature_note": "Toast's own contract and fee practice causes this; no feature in brain/company addresses it. A published fee schedule and no exit penalty would.",
      "cites": ["src:2", "src:4", "src:3", "src:5"]
    },
    {
      "id": "pain:deposit-doesnt-match-sales",
      "statement": "My deposits show up late, in odd amounts, or not at all, and they don't match last night's sales.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "Deposits arrive split into odd amounts, missing, or not matching the prior night's sales.",
        "operational": "The owner reconciles the bank against POS sales and chases support for days about missing payouts.",
        "personal": "A week without the payout the business runs on.",
        "personal_note": "From Despoina's Trustpilot review; no source describes the effect on paying suppliers or staff."
      },
      "workflow": "The morning after service, when the owner opens the business bank account to match the Toast deposit against the prior night's sales report.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Dated September 2026 Trustpilot complaints about Toast deposits and instant deposits failing or arriving in odd amounts.",
        "cites": ["src:4"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "Changing the bank account on file, which one owner says takes three to four weeks.",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "TOAST deposits and instant deposits fractured into odd amounts, or they don't appear at all.",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I have been getting the run around for the last 7 days and haven't received my payouts yet.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "Sometimes the amount settled into your account doesn’t match the sales from the night before.",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "After one month they didn't make the deposit, they say that the person in charge of my case is on vacation!",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Days to weeks without cash the business already earned, plus time reconciling.",
          "fears": "No source shows the fear directly; the quotes stop at missing and mismatched money.",
          "dream_outcome": "Each morning's deposit matches last night's sales, on time."
        }
      },
      "relief": {
        "line": "Not found. No buyer quote describes deposits that reconcile.",
        "says": [],
        "gap": "Read Trustpilot 4 and 5 star reviews on page 3; none mentions deposits or payouts."
      },
      "euphoria": {
        "line": "Not found.",
        "says": [],
        "gap": "No positive review read mentions cash flow or deposits."
      },
      "segments": ["seg:independent"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company covers payouts; a deposit report that ties each deposit to the night's sales would.",
      "cites": ["src:4", "src:3"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Owners in the reviews name and compare POS vendors they came from or left for (Revel, Clover, SpotOn, PayPal as backup), so they know solutions exist.",
      "cites": ["src:2", "src:5", "src:7"]
    }
  },
  "stats": [],
  "keywords": [
    "toast customer service",
    "toast pos cancellation fee",
    "toast deposit missing",
    "pos outage lost sales",
    "backup card processor restaurant",
    "offline transactions missing"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "Which pain did your last ten new customers name on the first sales call: support, outages, fees, or something else?",
      "why": "Priority here is ordered from public review volume, which overweights angry Toast users rather than prospects.",
      "would_change": "pains[].priority"
    },
    {
      "id": "q:pains-delivery-commission",
      "question": "Do prospects bring up third-party delivery commissions when they look at commission-free online ordering?",
      "why": "Only press articles quoting owners turned up on delivery commissions; no buyer-class page was read, so no pain row exists for feat:online.",
      "would_change": "pains[]"
    },
    {
      "id": "q:pains-payroll-tips",
      "question": "Do customers raise payroll or tip distribution problems, and with which tool?",
      "why": "One Trustpilot title said 'DO NOT USE TOAST PAYROLL' and one Square merchant said an outage disrupted payroll; not enough for a row on feat:labor.",
      "would_change": "pains[]"
    },
    {
      "id": "q:pains-unvoiced-features",
      "question": "When customers see Toast IQ, inventory sync or marketing, what problem do they say it solves for them?",
      "why": "No buyer source named a pain these features kill; that silence may be a finding or a gap in the sweep.",
      "would_change": "pains[].feature_ref"
    },
    {
      "id": "q:pains-multi-location",
      "question": "What do operations leads at multi-location groups say hurts that single owners don't?",
      "why": "Only one source spoke for seg:multi; review sites are dominated by single-location owners.",
      "would_change": "pains[].segments"
    }
  ],
  "sources": [
    {
